const generalLog: GravitoLogger = createLogger('mcp');

// ============================================================================
// TYPES
// ============================================================================

export interface MCPContent {
  content: Array<{ type: string; text: string }>;
}

export interface ExecutionContext {
  apiKey?: string;
  clientIp?: string;
  userAgent?: string;
  /**
   * TRUSTED authenticated tenant, resolved by the HTTP handler from a validated
   * inference credential (provisioned tenant key → org-<id>/user-<id>, spoof-
   * proof). Additive + optional: existing call sites compile unchanged and leave
   * it undefined. It is the ONLY input that can raise the canonical verdict
   * receipt's tenant binding to `authenticated_tenant`.
   */
  authenticatedTenant?: { tenantId: string; source: string };
}

// Tool arguments arrive as parsed JSON from JSON-RPC — untyped at the boundary.
// Each handler validates its own inputs. This is the explicit trust boundary.
type ToolArgs = Record<string, unknown>;
type ToolHandler = (args: ToolArgs, ctx: ExecutionContext) => Promise<MCPContent>;

 * 
 * Looks up the tool in the dispatch table first, then falls back to the
 * unified tool bridge for any remaining tools.
 */
export async function executeTool(
  toolName: string,
  args: Record<string, unknown>,
  ctx: ExecutionContext = {},
): Promise<MCPContent> {
  const startTime = Date.now();
  // Strip gravito. prefix for dispatch lookup
  const shortName = toolName.replace('gravito.', '');

  // ── CONTROL PLANE GATE: Every MCP tool call goes through enforce() ──
  try {
    const { enforce: cpEnforce, getEnforcementMode } = await import('../control-plane');
    const cpResult = await cpEnforce({
      agentId: ctx.userId || 'mcp-caller',
      action: `mcp:${shortName}`,
      content: JSON.stringify(args).slice(0, 500),
      surface: 'mcp',
      riskScore: 0.3,
      metadata: { toolName: shortName, callerType: 'mcp' },
    });
    const cpMode = getEnforcementMode();
    generalLog.info(`[ToolExecutor:ControlPlane:${cpMode}] ${shortName} — ${cpResult.allowed ? 'ALLOWED' : 'BLOCKED'}: ${cpResult.reason}`);

