export type AsyncJobStatus = 'queued' | 'running' | 'completed' | 'failed' | 'expired';

export interface AsyncJobProgress {
  percent: number;       // 0-100
  stage: string;         // Human-readable stage name
  updatedAt: number;     // Unix ms
}

export interface WebhookConfig {
  url: string;
  secret?: string;       // HMAC-SHA256 signing secret
  headers?: Record<string, string>;  // Custom headers
  maxRetries: number;
  retryDelayMs: number;
}

export interface AsyncJob {
  id: string;
  toolName: string;
  args: Record<string, unknown>;
  status: AsyncJobStatus;
  result?: unknown;
  error?: string;
  createdAt: number;     // Unix ms
  startedAt?: number;
  completedAt?: number;
  ttlMs: number;         // Time-to-live for result storage
  apiKey: string;
  clientIp: string;
  userAgent: string;
  progress?: AsyncJobProgress;
  webhook?: WebhookConfig;
  webhookDelivered?: boolean;
  webhookAttempts?: number;
}

export interface AsyncJobResponse {
  job_id: string;
  status: AsyncJobStatus;
  poll_url: string;
  poll_interval_ms: number;
  estimated_duration_ms: number;
  retry_after_s: number;           // Retry-After header value
  result?: unknown;
  error?: string;
  elapsed_ms?: number;
  progress?: AsyncJobProgress;
  webhook_configured?: boolean;
}

export interface CreateJobOptions {
  apiKey: string;
  clientIp: string;
  userAgent: string;
  callbackUrl?: string;
  callbackSecret?: string;
  callbackHeaders?: Record<string, string>;
}

// ============================================================================
// CONFIGURATION
// ============================================================================

const CONFIG = {
  /** Max jobs stored in memory */
  maxJobs: 1000,
  /** Default TTL for completed job results (5 minutes) */
  defaultTtlMs: 5 * 60 * 1000,
  /** Cleanup interval (every 60 seconds) */
  cleanupIntervalMs: 60 * 1000,
  /** Tools that should use async execution (LLM-dependent, >5s typical) */
  // DISABLED: All tools now execute synchronously for MCP CLI compatibility.
  // The timeout system (15s default, 55s for SLOW_TOOLS) handles long-running tools.
  // Async mode can be re-enabled per-request via x-prefer-async: true header.
/**
 * Create an async job for a tool call
 * Returns the job and the 202 response headers
 */
export function createAsyncJob(
  toolName: string,
  args: Record<string, unknown>,
  context: CreateJobOptions
): { job: AsyncJob; headers: Record<string, string> } {
  // Enforce max jobs limit
  if (jobs.size >= CONFIG.maxJobs) {
    evictOldestCompleted();
  }

  const id = `job_${Date.now()}_${crypto.randomBytes(6).toString('hex')}`;
  const shortName = toolName.replace('gravito.', '');
  const estimatedMs = CONFIG.estimatedDurations.get(shortName) || CONFIG.defaultEstimatedDuration;
  const retryAfterS = CONFIG.retryAfter.queued;

  const job: AsyncJob = {
    id,
    toolName,
    args,
    status: 'queued',
    createdAt: Date.now(),
    ttlMs: CONFIG.defaultTtlMs,
    apiKey: context.apiKey,
    clientIp: context.clientIp,
    userAgent: context.userAgent,
    progress: {
      percent: 0,
      stage: 'queued',
      updatedAt: Date.now(),
    },
  };

  // Configure webhook if callback URL provided
  if (context.callbackUrl) {
    job.webhook = {
      url: context.callbackUrl,
      secret: context.callbackSecret,
      headers: context.callbackHeaders,
      maxRetries: CONFIG.maxWebhookRetries,
      retryDelayMs: CONFIG.webhookRetryBaseMs,
    };
    job.webhookDelivered = false;
    job.webhookAttempts = 0;
  }

  jobs.set(id, job);
  generalLog.info(`[AsyncJobQueue] Created job ${id} for tool ${toolName} (webhook: ${!!context.callbackUrl})`);

  // Build 202 response headers
  const headers: Record<string, string> = {
    'Retry-After': String(retryAfterS),
    'X-Job-Id': id,
    'X-Estimated-Duration-Ms': String(estimatedMs),
    'X-Poll-Url': `/api/mcp/jobs/${id}`,
  };

  return { job, headers };
}

/**
 * Mark a job as running with progress update
 */
export function markRunning(jobId: string): void {
  const job = jobs.get(jobId);
  if (job) {
    job.status = 'running';
    job.startedAt = Date.now();

