/**
 * Execute a Gravito MCP tool by name.
 * 
 * Looks up the tool in the dispatch table first, then falls back to the
 * unified tool bridge for any remaining tools.
 */
export async function executeTool(
  toolName: string,
  args: Record<string, unknown>,
  ctx: ExecutionContext = {},
): Promise<MCPContent> {
  const startTime = Date.now();
  // Strip gravito. prefix for dispatch lookup
  const shortName = toolName.replace('gravito.', '');

  // ── CONTROL PLANE GATE: Every MCP tool call goes through enforce() ──
  try {
    const { enforce: cpEnforce, getEnforcementMode } = await import('../control-plane');
    const cpResult = await cpEnforce({
      agentId: ctx.userId || 'mcp-caller',
      action: `mcp:${shortName}`,
      content: JSON.stringify(args).slice(0, 500),
      surface: 'mcp',
      riskScore: 0.3,
      metadata: { toolName: shortName, callerType: 'mcp' },
    });
    const cpMode = getEnforcementMode();
    generalLog.info(`[ToolExecutor:ControlPlane:${cpMode}] ${shortName} — ${cpResult.allowed ? 'ALLOWED' : 'BLOCKED'}: ${cpResult.reason}`);
    if (cpResult.blocked && (cpMode === 'hard' || cpMode === 'soft')) {
      generalLog.warn(`[ToolExecutor:ControlPlane] BLOCKED tool ${shortName} in ${cpMode} mode: ${cpResult.reason}`);
      return mcpText({ error: `Control plane ${cpMode}-blocked: ${cpResult.reason}`, blocked: true });
    }
  } catch (cpErr) {
    generalLog.warn(`[ToolExecutor:ControlPlane] Error (non-fatal): ${String(cpErr)}`);
  }

  // ── Trust Boundary: Validate & coerce input before dispatch ──
  const validationError = validateToolInput(shortName, args || {});
  if (validationError) {
    generalLog.warn(`[ToolExecutor] Validation failed for ${shortName}:`, validationError.error);
    try { const { recordExecution } = await import('./tool-latency-tracker'); recordExecution(shortName, Date.now() - startTime, false); } catch {}
    return mcpText(validationError);
  }
  const coercedArgs = coerceToolInput(shortName, args || {});

  let success = true;
  try {
    // Check dispatch table first
    const handler = TOOL_DISPATCH[shortName];
    if (handler) {
      return await safeTool(() => handler(coercedArgs, ctx), shortName);
    }

    // Fallback: route through unified tool bridge
    return await safeTool(async () => {
      const bridge = getUnifiedToolBridge();
      const bridgeResult = await bridge.invokeTool(shortName, coercedArgs || {});
      return mcpText(bridgeResult);
    });
  } catch (err) {
    success = false;
    throw err;
  } finally {
    try { const { recordExecution } = await import('./tool-latency-tracker'); recordExecution(shortName, Date.now() - startTime, success); } catch {}
  }
}

/** Check if a tool has an explicit handler (not bridge passthrough) */
export function hasExplicitHandler(toolName: string): boolean {
  const shortName = toolName.replace('gravito.', '');
  return shortName in TOOL_DISPATCH;
}

/** Get all registered tool handler names */
export function getRegisteredHandlers(): string[] {
  return Object.keys(TOOL_DISPATCH);
}

